package stream

import (
	"path"
	"sort"
	"strconv"
	"strings"
	"time"
)

// timeNow is the package clock, overridable in tests for deterministic token
// expiry. Production uses time.Now.
var timeNow = time.Now

// Packaging states, exactly as the lane persists them in doc["streams"]
// (Interfaces §1). StateNone means no packaging has run for the item.
const (
	StateNone     = "none"
	StatePartial  = "partial"
	StateComplete = "complete"
	StateFailed   = "failed"
)

// Playback modes. ModeHls means a published build (partial or complete) is
// playable at the playlist URL; ModeDirect is the unconditional floor.
const (
	ModeDirect = "direct"
	ModeHls    = "hls"
)

// Descriptor honesty states (tv-playback-unblock D1): READ-SIDE projections a
// descriptor answers instead of the bare packaging state — never persisted.
// The persisted doc["streams"] namespace carries only the states above;
// StatePreparing means the direct floor is not <video>-native but a pack CAN
// land, StateUnsupported that packaging cannot help. state_reason names why.
// StateMissing (tombstone-lifecycle D6) means the direct floor's original file
// is absent on disk — answered by the composition root's one stat, never here
// (Describe stays fs-free over the document).
const (
	StatePreparing   = "preparing"
	StateUnsupported = "unsupported"
	StateMissing     = "missing"
)

// state_reason vocabulary (tv-playback-unblock D1/D3) — a closed set naming
// why a direct floor is not <video>-playable. Empty string on every other
// answer (hls, native-container floors, broken builds). ReasonFileMissing
// (tombstone-lifecycle D6) names the absent-original answer; like its state,
// it is applied by the composition root beside these values.
const (
	ReasonNonNativeContainer = "non_native_container"
	ReasonCodecNotOptedIn    = "codec_not_opted_in"
	ReasonCodecUnsupported   = "codec_unsupported"
	ReasonFileMissing        = "file_missing"
)

// SectionKindChapter is the only section kind produced in v1 (projected from
// container chapters). SectionKindMarker is reserved for future
// plugin-detected boundaries and MUST NOT be produced (spec: "Sections from
// container chapters").
const (
	SectionKindChapter = "chapter"
	SectionKindMarker  = "marker"
)

// Describe projects one item's stored document into the read-only playback
// descriptor (Interface 3; the GET /playback handler's ONE domain call). Pure:
// the document is read, never written, and the only computed secret is the
// freshly minted play token returned via the play URL.
//
// hls answers only over a partial/complete state whose stored playlist exists
// and whose build passes the D5 integrity guard (buildHealthy — read-only
// ValidateBuild; a broken or evicted build floors direct, partial builds and
// nonce-less namespaces exempt); every other item keeps the direct floor
// (INV-floor) with stateReason from floorReason — the honesty projection
// (tv-playback-unblock D1/D3: stored facts only, never a re-probe, never
// client input; the container law is containerNative, the matroska-asymmetry
// canonical; the pack verdicts ride PackGate, playback-capability-gate D1).
// A none-state non-native floor answers preparing (a pack can land) or
// unsupported (the codecs are the unmet gate); a failed state keeps its value
// and retry affordance, carrying only the non-native marker; nothing is
// persisted — doc["streams"] keeps its value. Cooldown-blind by design: a
// preparing item whose enqueue would be cooldown-refused stalls honestly (the
// ledger is not a document fact). codecs/codecsSrc are describeCodecs'
// recorded-wins answer, hls answers only (playback-capability-gate D2,
// pack-manifest-audio D7 — INV4: the source rides the decision log, the wire
// is untouched); layout is the lane's persisted layoutName, hls answers only
// (streamLayout — fix-tv-unblock-2 Interfaces 1); sections and voiceovers
// project stored facts only (projectChapters, projectVoiceovers —
// serial-watch-flow D-2), ordered, never a re-probe, never a write.
func (s *Service) Describe(itemID string, doc map[string]any) (mode, state, playURL string, sections, voiceovers []map[string]any, stateReason string, codecs []string, codecsSrc, layout string) {
	s.normalize()
	state = streamState(doc["streams"])
	voiceovers = projectVoiceovers(doc["parsed"])
	chapters := projectChapters(doc["ffprobe"])
	token, _ := s.Issue(itemID, timeNow())
	if state == StatePartial || state == StateComplete {
		if playlist := streamPlaylist(doc["streams"]); playlist != "" && s.buildHealthy(itemID, state, doc["streams"]) {
			codecs, src := describeCodecs(doc["streams"], doc["ffprobe"])
			return ModeHls, state, playlist + "?" + tokenQuery + "=" + token, chapters, voiceovers, "", codecs, src, streamLayout(doc["streams"])
		}
	}
	reason := s.floorReason(doc["ffprobe"], state)
	if state == StateNone && reason != "" {
		// The honesty projection (D1): a none-state floor the client cannot
		// decode answers preparing (the reason is the container alone) or
		// unsupported (the codecs are the unmet gate) — never persisted:
		// doc["streams"] keeps its none value.
		state = StateUnsupported
		if reason == ReasonNonNativeContainer {
			state = StatePreparing
		}
	}
	return ModeDirect, state, mediaPrefix + "/" + itemID + "/original?" + tokenQuery + "=" + token, chapters, voiceovers, reason, nil, codecsSrcNone, ""
}

// streamLayout reads the layout record the lane persisted at publish
// (doc["streams"].layout — fix-tv-unblock-2 Interfaces 1, the read side; the
// value is the lane's layoutName vocabulary verbatim). Empty when the
// namespace predates the record or the value is unreadable — the fail-open
// shape the SPA mounts through.
func streamLayout(v any) string {
	m, ok := v.(map[string]any)
	if !ok {
		return ""
	}
	s, _ := m["layout"].(string)
	return s
}

// The codecs source vocabulary (pack-manifest-audio D7): WHICH half of
// describeCodecs produced the descriptor's codecs answer. A plain string,
// the stateReason pattern — no new exported identifier; the value rides the
// playback decision log (cmd's codecs_src field), never the wire.
const (
	codecsSrcRecorded = "recorded" // the stored record (persisted at publish) answered
	codecsSrcLegacy   = "legacy"   // the read-side composition over stored source facts answered
	codecsSrcNone     = "none"     // neither half answered (fail-open absent), or no codecs field at all
)

// describeCodecs resolves the descriptor's additive codecs field for one hls
// answer (playback-capability-gate D2) plus WHICH half answered
// (pack-manifest-audio D7): the recorded value from the stored streams
// namespace wins whenever it is present (codecsSrcRecorded); a namespace
// predating the record composes the same strings read-side from the stored
// source ffprobe facts (codecsSrcLegacy). Pure — the document is already in
// hand; nothing is re-probed, and an uncomposable build answers nil with
// codecsSrcNone (fail-open, the field is simply absent).
func describeCodecs(streams, ffprobe any) ([]string, string) {
	if cs := recordedCodecs(streams); len(cs) > 0 {
		return cs, codecsSrcRecorded
	}
	if cs := legacyCodecs(ffprobe); len(cs) > 0 {
		return cs, codecsSrcLegacy
	}
	return nil, codecsSrcNone
}

// recordedCodecs reads the codec record the lane persisted at publish
// (doc["streams"].codecs — Interfaces §1, the read side). Nil when the
// namespace predates the record, when the value is unreadable, or when any
// entry is not a non-empty string — the legacy composition then gets its
// chance (D2: the recorded value wins, a broken one never answers).
func recordedCodecs(streams any) []string {
	m, ok := streams.(map[string]any)
	if !ok {
		return nil
	}
	raw, ok := m["codecs"].([]any)
	if !ok {
		return nil
	}
	out := make([]string, 0, len(raw))
	for _, c := range raw {
		s, ok := c.(string)
		if !ok || s == "" {
			return nil // an unreadable record is no record at all
		}
		out = append(out, s)
	}
	return out
}

// floorReason resolves the descriptor's state_reason for the direct floor
// (tv-playback-unblock D1/D3 — pure over stored facts): "" for a native
// container or any state the honesty projection does not answer; for a
// failed state only the non-native marker (the state itself keeps its value
// and its retry affordance); for a none-state non-native floor the PackGate
// verdict rides through (playback-capability-gate D1 — the same single judge
// every pack seam consults, its refusal tokens verbatim).
func (s *Service) floorReason(ffprobe any, state string) string {
	if containerNative(ffprobe) {
		return ""
	}
	if state == StateFailed {
		return ReasonNonNativeContainer
	}
	if state != StateNone {
		return "" // partial/complete/broken-build keep their persisted value
	}
	f, ok := ffprobe.(map[string]any)
	if !ok {
		return ReasonCodecUnsupported
	}
	switch PackGate(f, s.OptInCodecs) {
	case GateOpen:
		return ReasonNonNativeContainer
	case Gate(ReasonCodecNotOptedIn):
		return ReasonCodecNotOptedIn
	default: // ReasonCodecUnsupported
		return ReasonCodecUnsupported
	}
}

// containerNative reports whether the probed container is one a <video>
// element decodes natively: the mp4 family or webm — everything else
// (matroska/mkv, avi, mpegts, …) is not. Judged from the ffprobe format
// blob's format_name substrings; absent or unreadable facts read NOT native
// (fail-safe, INV2 — a floor disclaimed by mistake merely answers preparing,
// while an undecodable floor presented as native breaks playback).
//
// The matroska asymmetry's CANONICAL home (classification.go's
// containerAcceptable points here): ffprobe's shared demuxer reports
// "matroska,webm" for MKV and WebM alike, so the tag cannot disambiguate —
// any format_name containing "matroska" reads NOT native even though it also
// names webm. An MKV misread as native would hand the player an undecodable
// floor, while a WebM misread as not-native merely answers preparing for a
// pack that will land anyway.
func containerNative(ffprobe any) bool {
	f, ok := ffprobe.(map[string]any)
	if !ok {
		return false
	}
	format, _ := f["format"].(map[string]any)
	name, _ := format["format_name"].(string)
	name = strings.ToLower(name)
	if strings.Contains(name, "matroska") {
		return false // the shared demuxer names webm too — the tag cannot disambiguate
	}
	for _, good := range []string{"mp4", "m4a", "m4v", "mov", "webm"} {
		if strings.Contains(name, good) {
			return true
		}
	}
	return false
}

// buildHealthy gates the hls answer on the stored build still existing on
// disk (D5): true — hls proceeds as before — for every partial build and for
// any complete namespace without a nonce (byte-identical to the pre-guard
// behavior); for a complete build WITH a nonce it is exactly ValidateBuild's
// verdict. Strictly read-only: the check stats and reads the published
// directory, never a packaging-state write.
func (s *Service) buildHealthy(itemID string, state string, streams any) bool {
	if state != StateComplete {
		return true
	}
	m, ok := streams.(map[string]any)
	if !ok {
		return true
	}
	nonce, _ := m["nonce"].(string)
	if nonce == "" {
		return true
	}
	return s.ValidateBuild(itemID, nonce) == nil
}

// projectVoiceovers projects the episode document's parsed.sidecars into the
// descriptor's read-only voiceovers shape (serial-watch-flow D-2): document
// order, each entry {index, label} — index is the sidecar's document index
// (the same index the sidecar media variant resolves against), the label
// resolved by voiceoverLabel. Only AUDIO sidecars are voiceovers; subtitle
// sidecars and serial-level sidecars (parsed.series_sidecars) never project;
// no audio sidecars → an empty list. Stored facts only — never a re-probe,
// never a write.
func projectVoiceovers(parsed any) []map[string]any {
	out := []map[string]any{}
	p, ok := parsed.(map[string]any)
	if !ok {
		return out
	}
	raw, ok := p["sidecars"].([]any)
	if !ok {
		return out
	}
	for i, c := range raw {
		sc, ok := c.(map[string]any)
		if !ok {
			continue
		}
		if kind, _ := sc["kind"].(string); kind != "audio" {
			continue
		}
		out = append(out, map[string]any{
			"index": i,
			"label": voiceoverLabel(sc),
		})
	}
	return out
}

// voiceoverLabel resolves one voiceover's display label: the language fact
// when present, else the containing folder name, else the file name (D-2).
// Sidecar relative paths are scanner-stamped slash paths; an unreadable
// relative_path degrades to "".
func voiceoverLabel(sc map[string]any) string {
	if lang, _ := sc["language"].(string); strings.TrimSpace(lang) != "" {
		return lang
	}
	rel, _ := sc["relative_path"].(string)
	if dir := path.Dir(rel); dir != "." && dir != "/" && dir != "" {
		return path.Base(dir)
	}
	return path.Base(rel)
}

// streamState reads the packaging state from the stored streams namespace
// (Interfaces §1 — the lane owns the schema; this is the read side). An absent
// or unreadable namespace reads as StateNone.
func streamState(v any) string {
	m, ok := v.(map[string]any)
	if !ok {
		return StateNone
	}
	s, _ := m["state"].(string)
	switch s {
	case StatePartial, StateComplete, StateFailed:
		return s
	}
	return StateNone
}

// streamPlaylist reads the artifact pointer (a /media-relative playlist URL)
// from the stored streams namespace. Empty when absent.
func streamPlaylist(v any) string {
	m, ok := v.(map[string]any)
	if !ok {
		return ""
	}
	p, _ := m["playlist"].(string)
	return p
}

// projectChapters projects the verbatim ffprobe blob's chapters into the
// descriptor's section shape, ordered by start time. Only chapters — the
// marker kind is reserved and never produced (spec: "Sections from container
// chapters"). Unparseable or absent chapters yield an empty list; sections
// project from stored facts, never a re-probe.
func projectChapters(ffprobe any) []map[string]any {
	probe, ok := ffprobe.(map[string]any)
	if !ok {
		return nil
	}
	raw, ok := probe["chapters"].([]any)
	if !ok {
		return nil
	}
	out := make([]map[string]any, 0, len(raw))
	for _, c := range raw {
		ch, ok := c.(map[string]any)
		if !ok {
			continue
		}
		start, ok := chapterTime(ch, "start")
		if !ok {
			continue // a chapter without a usable start cannot be seeked to
		}
		sec := map[string]any{
			"kind":  SectionKindChapter,
			"start": round3(start),
		}
		if end, ok := chapterTime(ch, "end"); ok && end > start {
			sec["end"] = round3(end)
		}
		if title := strings.TrimSpace(chapterTitle(ch)); title != "" {
			sec["title"] = title
		}
		out = append(out, sec)
	}
	sort.SliceStable(out, func(i, j int) bool {
		return out[i]["start"].(float64) < out[j]["start"].(float64)
	})
	return out
}

// chapterTime resolves a chapter boundary in seconds: ffprobe reports both
// *_time ("12.345678", the scaled string) and the raw integer in the chapter's
// time_base. The string form is preferred; the raw form is converted when the
// base is readable. ok is false when neither is usable.
func chapterTime(ch map[string]any, field string) (float64, bool) {
	if v, ok := ch[field+"_time"].(string); ok {
		if f, err := strconv.ParseFloat(strings.TrimSpace(v), 64); err == nil {
			return f, true
		}
	}
	raw, ok := ch[field].(float64)
	if !ok {
		return 0, false
	}
	if num, den, ok := timeBase(ch); ok {
		return raw * num / den, true
	}
	return 0, false
}

// timeBase parses a chapter's "1/1000"-shaped time_base. ok is false when
// absent or malformed (the raw-integer fallback then gives up).
func timeBase(ch map[string]any) (num, den float64, ok bool) {
	tb, _ := ch["time_base"].(string)
	numS, denS, found := strings.Cut(tb, "/")
	n, err1 := strconv.ParseFloat(strings.TrimSpace(numS), 64)
	d, err2 := strconv.ParseFloat(strings.TrimSpace(denS), 64)
	if !found || err1 != nil || err2 != nil || n == 0 || d == 0 {
		return 0, 0, false
	}
	return n, d, true
}

// chapterTitle reads the chapter's title, tolerating absent facts. Real
// `ffprobe -show_chapters` output nests the title under tags.title; the
// top-level "title" is the fallback shape (the section must carry the title
// through either way — spec: chapters become sections with start, end, and
// title carried through).
func chapterTitle(ch map[string]any) string {
	if tags, ok := ch["tags"].(map[string]any); ok {
		if t, ok := tags["title"].(string); ok {
			return t
		}
	}
	t, _ := ch["title"].(string)
	return t
}

// round3 caps the wire precision of section boundaries (milliseconds — far
// below seek granularity, and it keeps the descriptor human-sized).
func round3(f float64) float64 {
	return float64(int64(f*1000+0.5)) / 1000
}
